import{_ as e,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"HTTPS 与 TLS","description":"","frontmatter":{"title":"HTTPS 与 TLS","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/core/web/network/tls.md","filePath":"frontend/guide/core/web/network/tls.md","lastUpdated":1785217527000}'),l={name:"frontend/guide/core/web/network/tls.md"};function o(n,a,s,h,d,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="https-与-tls" tabindex="-1">HTTPS 与 TLS <a class="header-anchor" href="#https-与-tls" aria-label="Permalink to &quot;HTTPS 与 TLS&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>HTTPS 是在经过认证和加密的传输通道中使用 HTTP。TLS 负责协商密钥、验证通信对端并保护传输完整性；HTTP 继续负责方法、状态、字段和内容语义。地址栏出现锁形标志，只能说明浏览器与当前站点之间的连接满足相应安全条件，不能证明网站业务可信、内容无害或用户账号不会被钓鱼。</p><p>本篇以浏览器访问公开网站时最常见的 TLS 1.3 为主，解释证书、握手、会话恢复、HSTS、混合内容和排障证据。密码学算法证明、证书机构运营细节和服务端加固清单不在本篇展开。</p><h2 id="_1-https-提供什么" tabindex="-1">1. HTTPS 提供什么 <a class="header-anchor" href="#_1-https-提供什么" aria-label="Permalink to &quot;1. HTTPS 提供什么&quot;">​</a></h2><h3 id="_1-1-confidentiality" tabindex="-1">1.1 Confidentiality <a class="header-anchor" href="#_1-1-confidentiality" aria-label="Permalink to &quot;1.1 Confidentiality&quot;">​</a></h3><p>握手完成后，HTTP 请求与响应内容经过加密。网络路径上的普通观察者无法直接读取 URL path、查询参数、字段和正文。</p><p>仍可能暴露的信息包括目标 IP、流量大小、时序和连接行为。DNS 查询是否加密取决于 DNS 方案；传统 TLS 中的 SNI 也可能暴露目标主机名。</p><h3 id="_1-2-integrity" tabindex="-1">1.2 Integrity <a class="header-anchor" href="#_1-2-integrity" aria-label="Permalink to &quot;1.2 Integrity&quot;">​</a></h3><p>TLS 记录包含认证保护。传输途中被修改、插入或删除的数据通常会导致验证失败并终止连接，攻击者不能在不被发现的情况下随意改写 HTTP 内容。</p><p>TLS 不验证业务数据本身是否正确。服务器返回错误价格或前端错误处理输入，仍是应用层问题。</p><h3 id="_1-3-authentication" tabindex="-1">1.3 Authentication <a class="header-anchor" href="#_1-3-authentication" aria-label="Permalink to &quot;1.3 Authentication&quot;">​</a></h3><p>公开网站通常使用服务器证书向客户端证明：当前连接的对端持有与目标主机名对应证书的私钥，且证书链可追溯到浏览器信任的根。</p><p>客户端证书也可以实现双向 TLS（mTLS），但普通消费级网站很少要求浏览器用户配置客户端证书。</p><h3 id="_1-4-https-不保证什么" tabindex="-1">1.4 HTTPS 不保证什么 <a class="header-anchor" href="#_1-4-https-不保证什么" aria-label="Permalink to &quot;1.4 HTTPS 不保证什么&quot;">​</a></h3><ul><li>不保证域名背后的组织值得信任；</li><li>不阻止站点自己的脚本窃取页面数据；</li><li>不替代身份认证、授权、输入校验和内容安全策略；</li><li>不隐藏目标 IP、流量形态或所有域名信息；</li><li>不保护已经到达服务器后的明文数据。</li></ul><h2 id="_2-tls-的参与对象" tabindex="-1">2. TLS 的参与对象 <a class="header-anchor" href="#_2-tls-的参与对象" aria-label="Permalink to &quot;2. TLS 的参与对象&quot;">​</a></h2><h3 id="_2-1-client" tabindex="-1">2.1 Client <a class="header-anchor" href="#_2-1-client" aria-label="Permalink to &quot;2.1 Client&quot;">​</a></h3><p>浏览器发起握手，提供支持的 TLS 版本、密码套件、密钥交换参数、SNI、ALPN 等能力，并验证服务端证书与握手证明。</p><h3 id="_2-2-server" tabindex="-1">2.2 Server <a class="header-anchor" href="#_2-2-server" aria-label="Permalink to &quot;2.2 Server&quot;">​</a></h3><p>服务端选择双方共同支持的参数，发送证书链，证明自己持有对应私钥，并与客户端建立共享会话密钥。</p><p>TLS 可能终止在 CDN、负载均衡器或反向代理，而不是业务应用进程。边缘到源站之间是否再次使用 TLS，需要单独确认。</p><h3 id="_2-3-certificate-authority" tabindex="-1">2.3 Certificate Authority <a class="header-anchor" href="#_2-3-certificate-authority" aria-label="Permalink to &quot;2.3 Certificate Authority&quot;">​</a></h3><p>证书机构签发或签署证书。浏览器和操作系统维护根证书信任库，借助中间证书把站点证书连接到受信任根。</p><p>信任库不是通过页面下载得到的。把服务端随意提供的根证书当作可信根，会破坏证书验证的意义。</p><h3 id="_2-4-session" tabindex="-1">2.4 Session <a class="header-anchor" href="#_2-4-session" aria-label="Permalink to &quot;2.4 Session&quot;">​</a></h3><p>一次完整握手可以建立可恢复的会话信息。后续连接使用会话票据等机制恢复，减少握手成本，但仍会建立新的流量密钥。</p><h2 id="_3-证书与信任链" tabindex="-1">3. 证书与信任链 <a class="header-anchor" href="#_3-证书与信任链" aria-label="Permalink to &quot;3. 证书与信任链&quot;">​</a></h2><h3 id="_3-1-站点证书" tabindex="-1">3.1 站点证书 <a class="header-anchor" href="#_3-1-站点证书" aria-label="Permalink to &quot;3.1 站点证书&quot;">​</a></h3><p>证书把公钥、主体名称、有效期、用途和签发者等信息绑定在一起。服务端通过握手签名证明自己持有与证书公钥对应的私钥。</p><p>证书本身通常是公开信息。安全性依赖私钥保密、签名验证和信任链，而不是隐藏证书文件。</p><h3 id="_3-2-san-与主机名" tabindex="-1">3.2 SAN 与主机名 <a class="header-anchor" href="#_3-2-san-与主机名" aria-label="Permalink to &quot;3.2 SAN 与主机名&quot;">​</a></h3><p>浏览器主要使用 Subject Alternative Name（SAN）检查目标主机名：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DNS: example.com</span></span>\n<span class="line"><span>DNS: www.example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>*.example.com</code> 可以匹配 <code>api.example.com</code>，但不能匹配 <code>example.com</code>，也不能跨越多级匹配 <code>a.b.example.com</code>。</p><p>访问 IP 地址时，证书需要相应的 IP 地址标识；仅把 IP 写进普通 DNS 名称并不等价。</p><h3 id="_3-3-中间证书" tabindex="-1">3.3 中间证书 <a class="header-anchor" href="#_3-3-中间证书" aria-label="Permalink to &quot;3.3 中间证书&quot;">​</a></h3><p>常见链路是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>站点证书 -&gt; 中间 CA -&gt; 根 CA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>服务端通常发送站点证书和必要的中间证书，不发送根证书也可以，因为根已在客户端信任库中。若漏发中间证书，部分设备可能因无法构建证书链而失败。</p><h3 id="_3-4-有效期与用途" tabindex="-1">3.4 有效期与用途 <a class="header-anchor" href="#_3-4-有效期与用途" aria-label="Permalink to &quot;3.4 有效期与用途&quot;">​</a></h3><p>浏览器检查当前时间是否落在 <code>notBefore</code> 与 <code>notAfter</code> 之间，并检查证书是否允许服务器认证。设备时钟严重错误也会表现为“证书尚未生效”或“已过期”。</p><h3 id="_3-5-吊销信息" tabindex="-1">3.5 吊销信息 <a class="header-anchor" href="#_3-5-吊销信息" aria-label="Permalink to &quot;3.5 吊销信息&quot;">​</a></h3><p>证书可能通过 CRL、OCSP 或浏览器厂商维护的机制处理吊销。不同客户端的网络、隐私和可用性策略不同，不能假设每次连接都会同步查询并硬失败。</p><h2 id="_4-tls-1-3-握手" tabindex="-1">4. TLS 1.3 握手 <a class="header-anchor" href="#_4-tls-1-3-握手" aria-label="Permalink to &quot;4. TLS 1.3 握手&quot;">​</a></h2><h3 id="_4-1-clienthello" tabindex="-1">4.1 <code>ClientHello</code> <a class="header-anchor" href="#_4-1-clienthello" aria-label="Permalink to &quot;4.1 `ClientHello`&quot;">​</a></h3><p>客户端首先发送：</p><ul><li>支持的 TLS 版本与密码套件；</li><li>临时密钥交换参数（key share）；</li><li>随机数；</li><li>SNI 指定目标主机；</li><li>ALPN 声明 <code>h2</code>、<code>http/1.1</code> 等应用协议；</li><li>可选的会话恢复信息。</li></ul><p>TLS 1.3 的普通 <code>ClientHello</code> 仍有部分元数据未加密。Encrypted ClientHello（ECH）用于进一步保护 ClientHello 中的敏感名称，但部署和客户端支持具有兼容性边界。</p><h3 id="_4-2-serverhello" tabindex="-1">4.2 <code>ServerHello</code> <a class="header-anchor" href="#_4-2-serverhello" aria-label="Permalink to &quot;4.2 `ServerHello`&quot;">​</a></h3><p>服务端选择协议参数与 key share。双方据此计算共享秘密并派生握手密钥，后续大部分握手消息受到加密保护。</p><p>这里使用的是密钥协商，不是服务端用证书公钥直接加密整个 HTTP 会话。</p><h3 id="_4-3-certificate-与-certificateverify" tabindex="-1">4.3 Certificate 与 CertificateVerify <a class="header-anchor" href="#_4-3-certificate-与-certificateverify" aria-label="Permalink to &quot;4.3 Certificate 与 CertificateVerify&quot;">​</a></h3><p>服务端发送证书链，并用证书私钥对当前握手上下文签名。客户端同时验证：</p><ol><li>主机名是否匹配；</li><li>证书是否在有效期；</li><li>链是否能连接到信任根；</li><li>签名和用途是否有效；</li><li>握手证明是否与当前连接绑定。</li></ol><h3 id="_4-4-finished" tabindex="-1">4.4 Finished <a class="header-anchor" href="#_4-4-finished" aria-label="Permalink to &quot;4.4 Finished&quot;">​</a></h3><p>双方发送 Finished 消息，证明自己拥有从本次握手派生的密钥并看到了相同握手记录。验证完成后，HTTP 应用数据使用独立的流量密钥加密传输。</p><h3 id="_4-5-握手往返" tabindex="-1">4.5 握手往返 <a class="header-anchor" href="#_4-5-握手往返" aria-label="Permalink to &quot;4.5 握手往返&quot;">​</a></h3><p>TLS 1.3 的常规完整握手通常可以在一个网络往返后开始发送应用数据。实际页面耗时还包括 DNS、TCP 或 QUIC 建连、证书验证、拥塞控制和服务器处理，不能把 Network 面板中的所有连接时间都归因于 TLS。</p><h2 id="_5-证书验证失败" tabindex="-1">5. 证书验证失败 <a class="header-anchor" href="#_5-证书验证失败" aria-label="Permalink to &quot;5. 证书验证失败&quot;">​</a></h2><h3 id="_5-1-主机名不匹配" tabindex="-1">5.1 主机名不匹配 <a class="header-anchor" href="#_5-1-主机名不匹配" aria-label="Permalink to &quot;5.1 主机名不匹配&quot;">​</a></h3><p>访问 <code>https://api.example.com</code>，证书却只包含 <code>www.example.com</code>。反向代理默认站点、DNS 指向错误或证书遗漏子域都可能造成该问题。</p><h3 id="_5-2-证书过期或尚未生效" tabindex="-1">5.2 证书过期或尚未生效 <a class="header-anchor" href="#_5-2-证书过期或尚未生效" aria-label="Permalink to &quot;5.2 证书过期或尚未生效&quot;">​</a></h3><p>检查站点证书有效期，也检查客户端系统时间。自动续期成功不代表新证书已经部署到所有 CDN 节点和负载均衡实例。</p><h3 id="_5-3-信任链不完整" tabindex="-1">5.3 信任链不完整 <a class="header-anchor" href="#_5-3-信任链不完整" aria-label="Permalink to &quot;5.3 信任链不完整&quot;">​</a></h3><p>服务端漏发中间证书时，某些曾缓存该中间证书的设备可能正常，干净环境或其他平台失败。必须在不同信任库和无历史缓存的环境验证完整链。</p><h3 id="_5-4-自签名证书" tabindex="-1">5.4 自签名证书 <a class="header-anchor" href="#_5-4-自签名证书" aria-label="Permalink to &quot;5.4 自签名证书&quot;">​</a></h3><p>自签名证书没有连接到客户端已信任根。开发环境可以把内部根 CA 明确安装到受控设备，不能指导普通用户忽略生产证书警告。</p><h3 id="_5-5-代理拦截" tabindex="-1">5.5 代理拦截 <a class="header-anchor" href="#_5-5-代理拦截" aria-label="Permalink to &quot;5.5 代理拦截&quot;">​</a></h3><p>企业代理、安全软件或恶意网络可能使用本机已安装的根证书重新签发站点证书。若只有部分设备看到不同签发者，应检查系统代理和证书信任库。</p><h2 id="_6-alpn-与-http-版本" tabindex="-1">6. ALPN 与 HTTP 版本 <a class="header-anchor" href="#_6-alpn-与-http-版本" aria-label="Permalink to &quot;6. ALPN 与 HTTP 版本&quot;">​</a></h2><h3 id="_6-1-应用协议协商" tabindex="-1">6.1 应用协议协商 <a class="header-anchor" href="#_6-1-应用协议协商" aria-label="Permalink to &quot;6.1 应用协议协商&quot;">​</a></h3><p>ALPN 在 TLS 握手中协商连接承载的应用协议。客户端可声明：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h2, http/1.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>服务端选择双方支持的一项。若选择 <code>h2</code>，后续使用 HTTP/2；选择 <code>http/1.1</code> 则使用 HTTP/1.1。</p><h3 id="_6-2-http-3" tabindex="-1">6.2 HTTP/3 <a class="header-anchor" href="#_6-2-http-3" aria-label="Permalink to &quot;6.2 HTTP/3&quot;">​</a></h3><p>HTTP/3 运行在 QUIC 上，并集成 TLS 1.3 握手，不使用传统“先 TCP 再 TLS”的连接栈。浏览器通常先通过 DNS HTTPS 记录、<code>Alt-Svc</code> 或既有信息发现 HTTP/3 可用性。</p><p>HTTP/2 帧、多路复用、QUIC 丢包恢复和迁移属于“HTTP/2 与 HTTP/3”原理文章，本篇只说明 TLS 的连接关系。</p><h3 id="_6-3-版本回退" tabindex="-1">6.3 版本回退 <a class="header-anchor" href="#_6-3-版本回退" aria-label="Permalink to &quot;6.3 版本回退&quot;">​</a></h3><p>未协商到 HTTP/2/3 不代表 HTTPS 失败，可能安全回退到 HTTPS 上的 HTTP/1.1。协议版本应在 DevTools Protocol 列或连接工具中确认，不能根据 URL 猜测。</p><h2 id="_7-会话恢复与-0-rtt" tabindex="-1">7. 会话恢复与 0-RTT <a class="header-anchor" href="#_7-会话恢复与-0-rtt" aria-label="Permalink to &quot;7. 会话恢复与 0-RTT&quot;">​</a></h2><h3 id="_7-1-会话恢复" tabindex="-1">7.1 会话恢复 <a class="header-anchor" href="#_7-1-会话恢复" aria-label="Permalink to &quot;7.1 会话恢复&quot;">​</a></h3><p>TLS 1.3 服务端可以发放会话票据。客户端下次连接提交预共享密钥标识，双方省去部分完整认证工作，降低 CPU 和握手延迟。</p><p>票据应有有限生命周期并妥善轮换。CDN 多节点共享恢复密钥会扩大密钥管理范围。</p><h3 id="_7-2-0-rtt-early-data" tabindex="-1">7.2 0-RTT Early Data <a class="header-anchor" href="#_7-2-0-rtt-early-data" aria-label="Permalink to &quot;7.2 0-RTT Early Data&quot;">​</a></h3><p>恢复连接时，TLS 1.3 可允许客户端在握手完成前发送 early data。它减少一个往返，却不能提供与握手完成后数据相同的重放保护。</p><p>攻击者可能捕获并向另一个可接受节点重放 0-RTT 数据。支付、创建订单、发送验证码等非幂等操作不能仅依赖 TLS 防止重复执行。</p><h3 id="_7-3-应用边界" tabindex="-1">7.3 应用边界 <a class="header-anchor" href="#_7-3-应用边界" aria-label="Permalink to &quot;7.3 应用边界&quot;">​</a></h3><p>使用 0-RTT 需要服务端、边缘和业务共同限制：</p><ul><li>只接受可安全重放的请求；</li><li>对有副作用操作使用幂等键与服务端去重；</li><li>在不确定时拒绝 early data，等待完整握手；</li><li>记录 0-RTT 命中与重放防护指标。</li></ul><p>浏览器前端通常不能逐请求控制底层 TLS 0-RTT，因此关键保证必须落在服务端协议与业务语义中。</p><h2 id="_8-hsts-与-https-升级" tabindex="-1">8. HSTS 与 HTTPS 升级 <a class="header-anchor" href="#_8-hsts-与-https-升级" aria-label="Permalink to &quot;8. HSTS 与 HTTPS 升级&quot;">​</a></h2><h3 id="_8-1-strict-transport-security" tabindex="-1">8.1 <code>Strict-Transport-Security</code> <a class="header-anchor" href="#_8-1-strict-transport-security" aria-label="Permalink to &quot;8.1 `Strict-Transport-Security`&quot;">​</a></h3><p>HTTPS 响应可以发送：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Strict-Transport-Security</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> max-age=31536000; includeSubDomains</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>浏览器记录后，在有效期内把该主机的 HTTP 访问升级到 HTTPS，并对证书错误执行严格失败。该字段通过不安全 HTTP 返回时会被忽略。</p><h3 id="_8-2-includesubdomains" tabindex="-1">8.2 <code>includeSubDomains</code> <a class="header-anchor" href="#_8-2-includesubdomains" aria-label="Permalink to &quot;8.2 `includeSubDomains`&quot;">​</a></h3><p>它把策略应用到子域。启用前必须确认所有现有和未来子域都能提供有效 HTTPS；遗留 HTTP 子域会因此不可访问。</p><h3 id="_8-3-preload" tabindex="-1">8.3 Preload <a class="header-anchor" href="#_8-3-preload" aria-label="Permalink to &quot;8.3 Preload&quot;">​</a></h3><p>HSTS preload 把域名预置到浏览器列表，解决用户首次访问仍可能走 HTTP 的窗口。它有严格申请条件，移除传播也需要时间，不应把 preload 当作可立即撤销的开关。</p><h3 id="_8-4-重定向与-hsts-的区别" tabindex="-1">8.4 重定向与 HSTS 的区别 <a class="header-anchor" href="#_8-4-重定向与-hsts-的区别" aria-label="Permalink to &quot;8.4 重定向与 HSTS 的区别&quot;">​</a></h3><p><code>301/308</code> 是收到 HTTP 响应后再导航到 HTTPS；HSTS 可在发送不安全请求前由浏览器内部升级。仍应保留 HTTP 到 HTTPS 的服务端重定向，用于首次访问和不支持 HSTS 的客户端。</p><h2 id="_9-混合内容与安全上下文" tabindex="-1">9. 混合内容与安全上下文 <a class="header-anchor" href="#_9-混合内容与安全上下文" aria-label="Permalink to &quot;9. 混合内容与安全上下文&quot;">​</a></h2><h3 id="_9-1-mixed-content" tabindex="-1">9.1 Mixed Content <a class="header-anchor" href="#_9-1-mixed-content" aria-label="Permalink to &quot;9.1 Mixed Content&quot;">​</a></h3><p>HTTPS 页面加载 HTTP 脚本、样式、iframe 或 Fetch 会破坏传输保证。浏览器会阻止可主动修改页面的混合内容，并可能升级或限制部分被动内容。</p><p>修复方式是让所有依赖本身支持 HTTPS，并使用正确绝对 URL 或相对协议环境；不要通过关闭浏览器安全检查解决。</p><h3 id="_9-2-secure-context" tabindex="-1">9.2 Secure Context <a class="header-anchor" href="#_9-2-secure-context" aria-label="Permalink to &quot;9.2 Secure Context&quot;">​</a></h3><p>Service Worker、Web Crypto、剪贴板、媒体设备等能力可能要求 secure context。<code>https://</code> 通常满足要求，<code>http://localhost</code> 等本地开发来源有受限例外。</p><p>“API 因不安全上下文不可用”与“TLS 握手失败”是不同故障：前者通常已经加载页面，后者连可信 HTTPS 页面都无法建立。</p><h3 id="_9-3-cookie-属性" tabindex="-1">9.3 Cookie 属性 <a class="header-anchor" href="#_9-3-cookie-属性" aria-label="Permalink to &quot;9.3 Cookie 属性&quot;">​</a></h3><p><code>Secure</code> Cookie 只通过安全通道发送；<code>HttpOnly</code> 阻止脚本读取；<code>SameSite</code> 约束跨站发送。它们解决不同问题，启用 HTTPS 后仍需要按会话模型正确设置。</p><h2 id="_10-sni、代理与连接边界" tabindex="-1">10. SNI、代理与连接边界 <a class="header-anchor" href="#_10-sni、代理与连接边界" aria-label="Permalink to &quot;10. SNI、代理与连接边界&quot;">​</a></h2><h3 id="_10-1-sni" tabindex="-1">10.1 SNI <a class="header-anchor" href="#_10-1-sni" aria-label="Permalink to &quot;10.1 SNI&quot;">​</a></h3><p>多个域名可共享一个 IP。客户端在握手中通过 Server Name Indication 指定主机，边缘据此选择证书和站点配置。</p><p>若客户端没有发送正确 SNI，可能拿到默认站点证书并出现主机名不匹配。</p><h3 id="_10-2-tls-终止" tabindex="-1">10.2 TLS 终止 <a class="header-anchor" href="#_10-2-tls-终止" aria-label="Permalink to &quot;10.2 TLS 终止&quot;">​</a></h3><p>常见链路：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ==TLS A==&gt; CDN / 负载均衡 ==TLS B==&gt; 源站</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>TLS A 安全不自动证明 TLS B 已启用或正确验证源站证书。两段连接需要分别配置证书、主机名验证和最小协议版本。</p><h3 id="_10-3-前向代理" tabindex="-1">10.3 前向代理 <a class="header-anchor" href="#_10-3-前向代理" aria-label="Permalink to &quot;10.3 前向代理&quot;">​</a></h3><p>HTTP CONNECT 代理可以转发加密隧道而不解密内容；安装受信任根的检查代理则可能终止 TLS、检查内容再建立新连接。浏览器看到的证书签发者可帮助区分两者。</p><h2 id="_11-诊断-https-故障" tabindex="-1">11. 诊断 HTTPS 故障 <a class="header-anchor" href="#_11-诊断-https-故障" aria-label="Permalink to &quot;11. 诊断 HTTPS 故障&quot;">​</a></h2><h3 id="_11-1-先分类" tabindex="-1">11.1 先分类 <a class="header-anchor" href="#_11-1-先分类" aria-label="Permalink to &quot;11.1 先分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>优先检查</th></tr></thead><tbody><tr><td>证书名称错误</td><td>SAN、SNI、DNS 指向、默认虚拟主机</td></tr><tr><td>证书过期</td><td>节点证书、自动续期部署、客户端时间</td></tr><tr><td>只有部分设备失败</td><td>中间证书、旧 TLS 支持、信任库、代理</td></tr><tr><td>HTTPS 页面部分资源失败</td><td>Mixed Content、CSP、子资源证书</td></tr><tr><td>协议仍是 HTTP/1.1</td><td>ALPN、边缘配置、代理支持</td></tr><tr><td>首次 HTTP 请求仍出现</td><td>HSTS 是否已记录、是否 preload</td></tr></tbody></table><h3 id="_11-2-浏览器证据" tabindex="-1">11.2 浏览器证据 <a class="header-anchor" href="#_11-2-浏览器证据" aria-label="Permalink to &quot;11.2 浏览器证据&quot;">​</a></h3><p>在 DevTools 的 Security 与 Network 面板确认：</p><ul><li>主文档是否为安全来源；</li><li>证书的 SAN、签发者、有效期和链；</li><li>失败的是主文档还是某个子资源；</li><li>Protocol 列实际使用 <code>h3</code>、<code>h2</code> 或 <code>http/1.1</code>；</li><li>Console 是否报告 Mixed Content 或证书错误。</li></ul><h3 id="_11-3-命令行复核" tabindex="-1">11.3 命令行复核 <a class="header-anchor" href="#_11-3-命令行复核" aria-label="Permalink to &quot;11.3 命令行复核&quot;">​</a></h3><p><code>curl</code> 可以显示连接和协议协商：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关注输出中的证书主体、签发者、ALPN 选择、TLS 版本和响应头。具体字段随 curl 的 TLS 后端而异。</p><p>已安装 OpenSSL 时，可显式携带 SNI 查看服务端链：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com:443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -servername</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -showcerts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>命令成功连接不等于浏览器一定信任证书；还要检查 verify result，并考虑两者使用的信任库不同。</p><h3 id="_11-4-完整排障案例" tabindex="-1">11.4 完整排障案例 <a class="header-anchor" href="#_11-4-完整排障案例" aria-label="Permalink to &quot;11.4 完整排障案例&quot;">​</a></h3><p>症状：桌面 Chrome 正常，部分 Android 设备报告证书不受信任。</p><p>证据：</p><ol><li>DNS 在所有设备指向同一 CDN；</li><li>站点证书主机名和有效期正确；</li><li>桌面浏览器能从本地缓存补齐中间证书；</li><li><code>openssl s_client -showcerts</code> 显示服务端只发送站点证书；</li><li>干净移动设备无法构建到受信任根的链。</li></ol><p>修复：在 CDN 证书配置中部署站点证书与正确中间证书链，不额外发送根证书。</p><p>验收：用无历史缓存的目标系统重新连接，证书链验证成功；监控各节点证书指纹与到期时间。</p><h2 id="_12-常见误区" tabindex="-1">12. 常见误区 <a class="header-anchor" href="#_12-常见误区" aria-label="Permalink to &quot;12. 常见误区&quot;">​</a></h2><h3 id="_12-1-证书加密了所有数据" tabindex="-1">12.1 “证书加密了所有数据” <a class="header-anchor" href="#_12-1-证书加密了所有数据" aria-label="Permalink to &quot;12.1 “证书加密了所有数据”&quot;">​</a></h3><p>证书用于身份与握手证明，应用数据由握手派生的对称流量密钥加密。</p><h3 id="_12-2-https-会隐藏完整-url" tabindex="-1">12.2 “HTTPS 会隐藏完整 URL” <a class="header-anchor" href="#_12-2-https-会隐藏完整-url" aria-label="Permalink to &quot;12.2 “HTTPS 会隐藏完整 URL”&quot;">​</a></h3><p>path、query 和 fragment 不会以 HTTP 明文暴露给普通链路观察者，但目标 IP、流量特征，以及未受 ECH 保护的域名信息仍可能可见。URL 仍会进入浏览器历史、日志和应用监控，不应放长期密钥。</p><h3 id="_12-3-有锁就说明网站可信" tabindex="-1">12.3 “有锁就说明网站可信” <a class="header-anchor" href="#_12-3-有锁就说明网站可信" aria-label="Permalink to &quot;12.3 “有锁就说明网站可信”&quot;">​</a></h3><p>锁表示到该域名的连接受保护并通过浏览器验证，不代表域名属于用户原本想找的组织，也不审计页面业务。</p><h3 id="_12-4-tls-1-3-的-0-rtt-可以安全重试任何请求" tabindex="-1">12.4 “TLS 1.3 的 0-RTT 可以安全重试任何请求” <a class="header-anchor" href="#_12-4-tls-1-3-的-0-rtt-可以安全重试任何请求" aria-label="Permalink to &quot;12.4 “TLS 1.3 的 0-RTT 可以安全重试任何请求”&quot;">​</a></h3><p>0-RTT 存在重放风险。非幂等业务必须拒绝或在应用层去重。</p><h3 id="_12-5-cdn-配了-https-源站自然也是安全的" tabindex="-1">12.5 “CDN 配了 HTTPS，源站自然也是安全的” <a class="header-anchor" href="#_12-5-cdn-配了-https-源站自然也是安全的" aria-label="Permalink to &quot;12.5 “CDN 配了 HTTPS，源站自然也是安全的”&quot;">​</a></h3><p>浏览器到 CDN 与 CDN 到源站是两段独立连接。源站段可能是明文、忽略证书错误或错误验证主机，需要单独审计。</p><h2 id="_13-总结" tabindex="-1">13. 总结 <a class="header-anchor" href="#_13-总结" aria-label="Permalink to &quot;13. 总结&quot;">​</a></h2><ul><li>HTTPS 把 HTTP 放入经过认证、加密并具备完整性保护的通道，但不等于网站和业务本身可信。</li><li>浏览器通过 SAN、有效期、用途、签名和信任链验证证书，服务端必须发送完整的必要中间链。</li><li>TLS 1.3 通过 ClientHello、ServerHello、证书证明和 Finished 建立流量密钥；ALPN 决定 HTTP/2 或 HTTP/1.1 等应用协议。</li><li>会话恢复降低握手成本，0-RTT 则额外带来重放边界。</li><li>HSTS、全站 HTTPS、Secure Cookie 和混合内容治理共同维持页面安全上下文。</li><li>排障时要分别核对 DNS、证书、链、SNI、ALPN、客户端信任库和每一段 TLS 终止位置。</li></ul><h2 id="_14-参考资料" tabindex="-1">14. 参考资料 <a class="header-anchor" href="#_14-参考资料" aria-label="Permalink to &quot;14. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.rfc-editor.org/rfc/rfc8446" target="_blank" rel="noreferrer">RFC 8446: The Transport Layer Security (TLS) Protocol Version 1.3</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc6066" target="_blank" rel="noreferrer">RFC 6066: TLS Extensions - Server Name Indication</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc7301" target="_blank" rel="noreferrer">RFC 7301: TLS Application-Layer Protocol Negotiation</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc6797" target="_blank" rel="noreferrer">RFC 6797: HTTP Strict Transport Security</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Transport_Layer_Security" target="_blank" rel="noreferrer">MDN: Transport Layer Security</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/Security/Mixed_content" target="_blank" rel="noreferrer">MDN: Mixed content</a></li></ul>',155)])])}const T=e(l,[["render",o]]);export{u as __pageData,T as default};
